    {
        return ':root{--p:'.$primary.';--ink:#0f172a;--muted:#64748b;--line:#e2e8f0;--bg:#f8fafc}*{box-sizing:border-box}body{margin:0;font:15px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,"Noto Sans Arabic",sans-serif;color:var(--ink);background:var(--bg);display:flex;min-height:100vh}'
            .'nav.side{width:230px;background:#0f172a;color:#cbd5e1;padding:1rem;display:flex;flex-direction:column;gap:.25rem}nav.side a,nav.side .link{color:#cbd5e1;text-decoration:none;padding:.45rem .6rem;border-radius:.5rem;background:none;border:0;font:inherit;text-align:start;cursor:pointer}nav.side a.active,nav.side a:hover{background:#1e293b;color:#fff}.brand{color:#fff;margin-bottom:.75rem}'
            .'main{flex:1;padding:1.5rem;max-width:1100px;min-width:0}.title{font-size:1.4rem;margin:0 0 1rem}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:1rem;margin-bottom:1rem}.narrow{max-width:420px;margin:3rem auto}'
            .'label{display:block;margin-bottom:.8rem;font-weight:600;font-size:.9rem}label.check{display:flex;gap:.5rem;align-items:center}input,select,textarea{display:block;width:100%;margin-top:.25rem;padding:.6rem .7rem;border:1px solid #cbd5e1;border-radius:10px;font:inherit}label.check input{width:auto;margin:0}'
            .'button,.button{display:inline-block;padding:.55rem .9rem;border-radius:10px;border:1px solid var(--line);background:#fff;color:var(--ink);font:inherit;font-weight:600;text-decoration:none;cursor:pointer}.primary{background:var(--p);border-color:var(--p);color:#fff}.danger{background:#e11d48;border-color:#e11d48;color:#fff}'
            .'.toolbar{display:flex;gap:.5rem;flex-wrap:wrap;align-items:center;margin-bottom:1rem}.toolbar form{flex:1;min-width:200px}.toolbar input{margin:0}.table{overflow-x:auto;background:#fff;border:1px solid var(--line);border-radius:14px}table{width:100%;border-collapse:collapse}th,td{padding:.6rem .75rem;border-bottom:1px solid var(--line);text-align:start;vertical-align:top}th{font-size:.8rem;color:var(--muted);text-transform:uppercase}.actions{white-space:nowrap}.actions a{color:var(--p)}'
            .'.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:1rem}.stat{display:flex;flex-direction:column;text-decoration:none;color:inherit}.stat strong{font-size:1.8rem}.icon{font-size:1.4rem}.muted{color:var(--muted);font-size:.85rem}.badge{display:inline-block;background:#eef2ff;border-radius:999px;padding:0 .5rem;margin:.1rem 0;font-size:.75rem}'
            .'.alert{padding:.7rem 1rem;border-radius:10px}.alert.success{background:#ecfdf5;color:#065f46}.alert.error,.error{color:#be123c}.alert.error{background:#fff1f2}.error{display:block;font-weight:400}.danger-zone{margin-top:1rem}'
            .'.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:.25rem}.day{background:#fff;border:1px solid var(--line);border-radius:8px;min-height:80px;padding:.3rem;font-size:.8rem}.day a{display:block;color:var(--p);text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.day.empty{background:none;border:0}.day.today{border-color:var(--p)}'
            .'.bars{display:flex;gap:.5rem;align-items:flex-end;height:120px}.bar{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%}.bar span{width:100%;background:var(--p);border-radius:6px 6px 0 0;min-height:2px}.bar small{color:var(--muted)}'
            .'.print{max-width:800px;margin:auto;background:#fff;padding:2rem}.print-table th{width:35%}.signatures{display:flex;justify-content:space-between;margin-top:4rem}.signatures p{border-top:1px solid var(--ink);padding-top:.5rem;width:40%}'
            .'@media print{nav.side,.no-print,.title{display:none}body{background:#fff}main{padding:0}}@media (max-width:760px){body{flex-direction:column}nav.side{width:auto;flex-direction:row;flex-wrap:wrap}}';
    }
}
